/* Account access and revision-checked cloud sync. No passwords enter planner state. */
(() => {
  const config=window.PLANNER_CLOUD_CONFIG||{};
  const recoveryLink=location.hash.includes('type=recovery');
  if(!config.url||!config.publishableKey)return;
  document.body.classList.add('cloud-locked');
  const shell=document.createElement('section');shell.id='accountGate';shell.innerHTML=`<div class="account-card"><a class="brand" href="#">✳ <span>content playground</span></a><p class="eyebrow">YOUR IDEAS. YOUR SPACE.</p><h1 id="authTitle">Welcome back.</h1><p class="muted">Sign in to your private plans, from any device. Team workspaces are shared only with their members.</p><div class="filters"><button type="button" id="loginTab" class="selected">Log in</button><button type="button" id="signupTab">Sign up</button></div><form id="accountForm"><label class="field">Email<input id="accountEmail" type="email" autocomplete="email" required></label><label class="field">Password<input id="accountPassword" type="password" autocomplete="current-password" minlength="10" required></label><button id="accountSubmit" class="dark" type="submit">Log in</button></form><button id="forgotPassword" type="button">Forgot password?</button><p id="accountMessage" role="status" aria-live="polite">Connecting to your account…</p><button id="legacyBackup" type="button" hidden>↓ Back up existing browser plans</button></div>`;document.body.append(shell);
  const bar=document.createElement('div');bar.id='accountBar';bar.innerHTML=`<div><label for="workspaceSelect">Workspace</label><select id="workspaceSelect"></select><span id="accountIdentity"></span></div><div><button id="cloudRetry">↻ Sync</button><button id="accountSettings">Team & account</button><button id="accountLogout">Log out</button></div>`;document.querySelector('main').prepend(bar);
  const notice=document.createElement('div');notice.id='cloudNotice';notice.hidden=true;document.querySelector('.workspace').prepend(notice);
  const dialog=document.createElement('dialog');dialog.id='teamDialog';document.body.append(dialog);
  let sdk=null,user=null,workspace=null,workspaces=[],revision=0,dirty=false,saving=false,loading=false,conflict=false,editCounter=0,timer,mode='login',switchingUser=null;
  const node=id=>document.getElementById(id);
  const key=()=>user&&workspace?'content-playground-account:'+user.id+':'+workspace.id:null;
  const setMessage=text=>node('accountMessage').textContent=text;
  const syncLabel=text=>{node('saveState').textContent=text};
  function showNotice(text,actions=[]){notice.hidden=false;notice.replaceChildren();const p=document.createElement('p');p.textContent=text;notice.append(p);actions.forEach(([label,run])=>{const b=document.createElement('button');b.textContent=label;b.onclick=run;notice.append(b)})}
  function emptyState(){const c={...structuredClone(defaultClient),id:uid(),name:'My first client',audience:'',tone:'',pillars:''};return {version:1,clients:[c],items:[],ideas:[],shoots:{},selectedClient:c.id,selectedMonth:initialMonth}}
  function valid(data){return data&&data.version===1&&Array.isArray(data.clients)&&data.clients.length&&data.clients.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&Array.isArray(c.counts))&&Array.isArray(data.items)&&data.items.every(i=>typeof i.id==='string'&&types.includes(i.type)&&Array.isArray(i.shots))&&Array.isArray(data.ideas)&&data.ideas.every(i=>typeof i.id==='string'&&typeof i.title==='string')&&data.shoots&&typeof data.shoots==='object'&&!Array.isArray(data.shoots)}
  function apply(data){if(!valid(data))throw Error('This workspace has invalid data. Restore a valid backup.');state=structuredClone(data);clientId=state.clients.some(c=>c.id===state.selectedClient)?state.selectedClient:state.clients[0].id;month=/^\d{4}-\d{2}$/.test(state.selectedMonth||'')?state.selectedMonth:initialMonth;render();node('accountIdentity').textContent=user.email;node('workspaceSelect').value=workspace.id}
  function cache(){try{localStorage.setItem(key(),JSON.stringify({payload:state,revision,pending:dirty}));return true}catch{showNotice('Device storage is full. Keep this tab open until cloud sync completes and download a backup.');return false}}
  function queue(){if(!user||!workspace||loading)return;dirty=true;editCounter++;cache();syncLabel('● Changes waiting to sync');clearTimeout(timer);timer=setTimeout(sync,600)}
  window.PlannerCloud={storageKey:key,queue};
  function lock(){document.body.classList.add('cloud-locked');['editor','exportDialog','teamDialog'].forEach(id=>node(id)?.close());node('content').replaceChildren();node('accountIdentity').textContent='';node('workspaceSelect').replaceChildren();}
  function migrationPrompt(){if(workspace.kind!=='personal')return;let legacy;try{legacy=JSON.parse(localStorage.getItem('content-playground-v1'))}catch{}if(!valid(legacy))return;
    let receipts=[];try{receipts=JSON.parse(localStorage.getItem('planner-imported-accounts')||'[]')}catch{}if(receipts.includes(user.id))return;
    showNotice('Existing plans were found in this browser, including any October preparation. Import them into your private account. The browser copy stays intact.',[['Import my existing plans',()=>importLegacy(legacy)],['Download original backup',()=>download(JSON.stringify(legacy,null,2),'original-browser-plans.json','application/json')]]);
  }
  async function importLegacy(source){if(workspace.kind!=='personal'||loading||saving)return;await sync();if(dirty||conflict){toast('Sync your current changes before importing.');return}
    if(!confirm('Import these browser plans into '+user.email+'’s private workspace? The original browser copy will be kept.'))return;
    const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(source)));const fingerprint=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');if(state.browserImports?.includes(fingerprint)){notice.hidden=true;toast('These browser plans are already in your account.');return}const merged=mergeLegacy(state,source);merged.browserImports=[...(merged.browserImports||[]),fingerprint];apply(merged);queue();await sync();if(!dirty){let receipts=[];try{receipts=JSON.parse(localStorage.getItem('planner-imported-accounts')||'[]')}catch{}if(!receipts.includes(user.id))receipts.push(user.id);localStorage.setItem('planner-imported-accounts',JSON.stringify(receipts));notice.hidden=true;toast('Existing plans imported and saved to your private account.')}
  }
  function mergeLegacy(current,source){const result=structuredClone(current),ids=new Map();source.clients.forEach(c=>{const id=uid();ids.set(c.id,id);result.clients.push({...structuredClone(c),id})});
    source.items.forEach(i=>result.items.push({...structuredClone(i),id:uid(),clientId:ids.get(i.clientId)||i.clientId,shots:(i.shots||[]).map(s=>({...s,id:uid()}))}));
    source.ideas.forEach(i=>result.ideas.push({...structuredClone(i),id:uid(),clientId:ids.get(i.clientId)||i.clientId}));
    Object.entries(source.shoots).forEach(([k,v])=>{const split=k.lastIndexOf('|'),id=k.slice(0,split);result.shoots[(ids.get(id)||id)+k.slice(split)]=structuredClone(v)});
    result.selectedClient=ids.get(source.selectedClient)||result.clients[0].id;result.selectedMonth=source.selectedMonth||result.selectedMonth;return result;
  }
  async function sync(){
    clearTimeout(timer);if(!user||!workspace||loading||saving||conflict||!dirty)return;
    saving=true;const version=editCounter,account=user.id,space=workspace.id,payload=structuredClone(state),expected=revision;syncLabel('● Saving to your account…');
    try{const {data,error}=await sdk.rpc('planner_save',{p_workspace:space,p_payload:payload,p_expected_revision:expected});if(error)throw error;if(user?.id!==account||workspace?.id!==space)return;revision=Number(data);dirty=editCounter!==version;cache();syncLabel(dirty?'● Changes waiting to sync':'● Saved to your account');if(!dirty)notice.hidden=true;
    }catch(error){if(user?.id!==account||workspace?.id!==space)return;dirty=true;cache();if(error.code==='40001'||String(error.message).includes('PLANNER_CONFLICT')){conflict=true;syncLabel('⚠ A newer cloud version exists');showNotice('Another device or teammate saved changes first. Your unsynced copy is kept on this device. Download it before loading the latest cloud version.',[['Download my unsynced copy',backup],['Load latest cloud version',reloadCloud]])}else{syncLabel('⚠ Not synced — saved on this device');showNotice('Cloud save failed. Your changes remain on this device. '+error.message,[['Retry sync',()=>sync()],['Download backup',backup]])}
    }finally{saving=false;if(dirty&&!conflict&&editCounter!==version)timer=setTimeout(sync,600)}
  }
  async function reloadCloud(){if(dirty&&!confirm('Load the latest cloud version? Download your unsynced copy first. Your unsynced cache will be replaced.'))return;dirty=false;conflict=false;await loadWorkspace(workspace.id,true)}
  async function loadWorkspace(id,discard=false){
    if(loading||saving)return;if(dirty&&!discard){await sync();if(dirty){node('workspaceSelect').value=workspace.id;toast('Resolve unsynced changes before changing workspaces.');return}}
    loading=true;document.body.classList.add('cloud-locked');setMessage('Loading your plans…');const next=workspaces.find(w=>w.id===id),account=user.id;workspace=next;clearTimeout(timer);notice.hidden=true;
    try{const {data,error}=await sdk.from('planner_documents').select('payload,revision').eq('workspace_id',id).maybeSingle();if(error)throw error;if(user?.id!==account)return;
      let saved=null;try{saved=JSON.parse(localStorage.getItem(key()))}catch{}
      revision=Number(data?.revision||0);conflict=false;dirty=false;
      if(!discard&&saved?.pending&&valid(saved.payload)){apply(saved.payload);dirty=true;conflict=saved.revision!==revision;revision=Number(saved.revision);showNotice(conflict?'This device has unsynced changes and the cloud has a newer version. Download this copy before reloading.':'Recovered unsynced changes from this device.',[['Download this copy',backup],['Load latest cloud version',reloadCloud]])}
      else {apply(data?.payload||emptyState());dirty=!data;}
      cache();syncLabel(conflict?'⚠ Resolve the newer cloud version':dirty?'● Changes waiting to sync':'● Saved to your account');document.body.classList.remove('cloud-locked');loading=false;if(dirty&&!conflict)await sync();if(!dirty)migrationPrompt();
    }catch(error){setMessage('Could not load your workspace. '+error.message);node('accountForm').hidden=true;const retry=document.createElement('button');retry.textContent='Retry loading plans';retry.onclick=()=>{retry.remove();loadWorkspace(id,true)};node('accountMessage').after(retry)}finally{loading=false}
  }
  async function refreshWorkspaces(){const {data,error}=await sdk.from('planner_workspaces').select('id,name,kind,owner_id').order('created_at');if(error)throw error;workspaces=data;node('workspaceSelect').innerHTML=data.map(w=>`<option value="${esc(w.id)}">${w.kind==='personal'?'🔒':'👥'} ${esc(w.name)}</option>`).join('')}
  async function signedIn(session){if(mode==='recovery'||(recoveryLink&&mode!=='recovery-finished'))return;if(!session?.user){user=null;workspace=null;dirty=false;revision=0;lock();node('accountForm').hidden=false;setMessage('Log in or create your personal account.');return}
    if(switchingUser===session.user.id||user?.id===session.user.id)return;switchingUser=session.user.id;user=session.user;lock();
    try{const {data,error}=await sdk.rpc('planner_personal_workspace');if(error)throw error;await refreshWorkspaces();await loadWorkspace(data)}catch(error){setMessage('Account connected, but cloud storage is not ready. '+error.message)}finally{switchingUser=null}
  }
  function selectMode(next){mode=next;node('loginTab').classList.toggle('selected',mode==='login');node('signupTab').classList.toggle('selected',mode==='signup');node('authTitle').textContent=mode==='signup'?'Your next chapter starts here.':'Welcome back.';node('accountSubmit').textContent=mode==='signup'?'Create my account':'Log in';node('accountPassword').autocomplete=mode==='signup'?'new-password':'current-password';node('accountPassword').minLength=mode==='signup'?10:1;setMessage('')}
  node('loginTab').onclick=()=>selectMode('login');node('signupTab').onclick=()=>selectMode('signup');
  node('accountForm').onsubmit=async event=>{event.preventDefault();if(!sdk){setMessage('Account service is still connecting. Please try again.');return}const button=node('accountSubmit');button.disabled=true;const email=node('accountEmail').value.trim(),password=node('accountPassword').value;setMessage(mode==='signup'?'Creating your account…':mode==='recovery'?'Updating your password…':'Logging in…');
    try{if(mode==='recovery'){const {error}=await sdk.auth.updateUser({password});if(error)throw error;node('accountPassword').value='';mode='recovery-finished';await signedIn((await sdk.auth.getSession()).data.session);return}
      const result=mode==='signup'?await sdk.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}}):await sdk.auth.signInWithPassword({email,password});if(result.error)throw result.error;node('accountPassword').value='';if(result.data.session)await signedIn(result.data.session);else setMessage('Check your inbox to confirm your email, then return here to log in.');
    }catch(error){setMessage(error.message)}finally{button.disabled=false}
  };
  node('forgotPassword').onclick=async()=>{if(!sdk)return;const email=node('accountEmail').value.trim();if(!email){setMessage('Enter your email first, then click Forgot password.');return}const {error}=await sdk.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});setMessage(error?error.message:'If an account exists, a password reset link will arrive by email.')};
  node('workspaceSelect').onchange=event=>loadWorkspace(event.target.value);
  node('cloudRetry').onclick=async()=>{if(conflict){toast('Use the conflict notice to download your copy and load the latest.');return}if(dirty)await sync();else await refreshCurrent()};
  node('accountLogout').onclick=async()=>{await sync();if(dirty&&!confirm('Some changes are not synced. They will remain in this account’s cache on this device. Download a backup before logging out if you need an extra copy. Log out anyway?'))return;const cacheKey=key(),wasDirty=dirty;const {error}=await sdk.auth.signOut();if(error){toast(error.message);return}if(!wasDirty&&cacheKey)localStorage.removeItem(cacheKey);await signedIn(null)};
  async function refreshCurrent(){if(!user||!workspace||loading||saving||dirty||node('editor').open||node('teamDialog').open||document.hidden)return;const account=user.id,space=workspace.id;const {data,error}=await sdk.from('planner_documents').select('payload,revision').eq('workspace_id',space).maybeSingle();if(user?.id!==account||workspace?.id!==space||dirty||saving||node('editor').open)return;if(error){syncLabel('⚠ Could not check for updates');return}if(data&&Number(data.revision)!==revision){revision=Number(data.revision);apply(data.payload);cache();syncLabel('● Latest plans loaded from your account')}}
  async function accountPanel(){
    dialog.innerHTML=`<div class="dialoghead"><h2>Team & account</h2><button type="button" class="close" aria-label="Close" id="closeTeam">×</button></div><p>Signed in as <b>${esc(user.email)}</b></p><p class="muted">Your private workspace is visible only to you. Team workspaces are editable by their owner and invited members.</p><h3>Create a team workspace</h3><form id="createTeamForm"><label class="field">Team name<input name="teamName" maxlength="100" required></label><button class="dark">Create workspace</button></form><div id="teamControls"></div><h3>Your invitations</h3><div id="pendingInvites">Loading…</div><p id="teamMessage" role="status"></p>`;node('closeTeam').onclick=()=>dialog.close();dialog.showModal();
    const message=text=>node('teamMessage').textContent=text;
    node('createTeamForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const {data,error}=await sdk.rpc('planner_create_team',{p_name:e.target.teamName.value});if(error)throw error;await refreshWorkspaces();dialog.close();await loadWorkspace(data)}catch(error){message(error.message)}finally{b.disabled=false}};
    if(workspace.kind==='personal'){node('teamControls').innerHTML='<p class="note">You’re in your private workspace. Switch to a team workspace to manage its members.</p>'}
    else if(workspace.owner_id===user.id){node('teamControls').innerHTML=`<h3>Invite a teammate</h3><form id="inviteForm"><label class="field">Teammate’s email<input name="inviteEmail" type="email" required></label><button>Invite to ${esc(workspace.name)}</button></form><p class="muted">An invitation appears in their account after they sign up and verify that email. No invitation email is sent automatically. Share your website link with them.</p><div id="memberList"></div>`;
      node('inviteForm').onsubmit=async e=>{e.preventDefault();const {error}=await sdk.rpc('planner_invite',{p_workspace:workspace.id,p_email:e.target.inviteEmail.value});message(error?error.message:'Invitation added. Ask your teammate to open Team & account after signing up.');if(!error){e.target.reset();await memberList()}};
      async function memberList(){const [members,invites]=await Promise.all([sdk.from('planner_members').select('user_id').eq('workspace_id',workspace.id),sdk.from('planner_invitations').select('id,email').eq('workspace_id',workspace.id)]);if(members.error||invites.error){message((members.error||invites.error).message);return}node('memberList').innerHTML='<h3>Members & pending invitations</h3>'+members.data.map(m=>`<p>Member ${esc(m.user_id.slice(0,8))} <button data-remove-member="${esc(m.user_id)}">Remove member</button></p>`).join('')+invites.data.map(i=>`<p>${esc(i.email)} · pending <button data-cancel-invite="${esc(i.id)}">Cancel invitation</button></p>`).join('');dialog.querySelectorAll('[data-remove-member]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this member’s access to this team workspace?'))return;const {error}=await sdk.rpc('planner_remove_member',{p_workspace:workspace.id,p_user:b.dataset.removeMember});if(error)message(error.message);else memberList()});dialog.querySelectorAll('[data-cancel-invite]').forEach(b=>b.onclick=async()=>{const {error}=await sdk.rpc('planner_cancel_invite',{p_invitation:b.dataset.cancelInvite});if(error)message(error.message);else memberList()})}await memberList();
    }else node('teamControls').innerHTML='<p class="note">You’re a member of this team. Its owner manages invitations and access.</p>';
    const {data,error}=await sdk.rpc('planner_pending_invites');node('pendingInvites').innerHTML=error?esc(error.message):data.length?data.map(i=>`<p>${esc(i.team_name)} <button data-accept-invite="${esc(i.id)}">Join workspace</button></p>`).join(''):'<p class="muted">No pending invitations. Ask your team owner to invite your sign-in email.</p>';
    dialog.querySelectorAll('[data-accept-invite]').forEach(b=>b.onclick=async()=>{const {data,error}=await sdk.rpc('planner_accept_invite',{p_invitation:b.dataset.acceptInvite});if(error){message(error.message);return}await refreshWorkspaces();dialog.close();await loadWorkspace(data)});
  }
  node('accountSettings').onclick=()=>accountPanel().catch(e=>toast(e.message));
  window.addEventListener('online',()=>{if(dirty&&!conflict)sync();else refreshCurrent()});window.addEventListener('focus',refreshCurrent);setInterval(refreshCurrent,30000);
  window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue=''}});
  let legacy;try{legacy=JSON.parse(localStorage.getItem('content-playground-v1'))}catch{}if(valid(legacy)){node('legacyBackup').hidden=false;node('legacyBackup').onclick=()=>download(JSON.stringify(legacy,null,2),'original-browser-plans.json','application/json')}
  async function boot(){try{if(!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(config.url)||config.publishableKey.startsWith('sb_secret_'))throw Error('Check the public Supabase project settings.');
    const module=await import('https://esm.sh/@supabase/supabase-js@2');sdk=module.createClient(config.url,config.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
    sdk.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){mode='recovery';lock();node('authTitle').textContent='Choose a new password';node('accountSubmit').textContent='Save new password';node('accountPassword').minLength=10;node('accountEmail').value=session?.user?.email||'';node('accountPassword').autocomplete='new-password';setMessage('Enter your new password below.');return}if(event==='SIGNED_OUT'){setTimeout(()=>signedIn(null),0)}else if(event==='SIGNED_IN'||event==='INITIAL_SESSION'){setTimeout(()=>signedIn(session),0)}});
    const {data,error}=await sdk.auth.getSession();if(error)throw error;if(recoveryLink||mode==='recovery')return;await signedIn(data.session);
  }catch(error){setMessage('Could not connect to accounts. '+error.message);node('accountSubmit').disabled=true}}
  if(recoveryLink)mode='recovery';
  boot();
})();
